<?php
declare(strict_types=1);namespace HyperfTest\Cases;
use App\Service\MeteringSchemaService;use App\Service\MeteringService;use Hyperf\Contract\IdGeneratorInterface;use Hyperf\DbConnection\Db;use Hyperf\Redis\Redis;use Mockery;use PHPUnit\Framework\TestCase;
final class MeteringServiceTest extends TestCase{protected function tearDown():void{Mockery::close();parent::tearDown();}public function testSchemaCreatesImmutableEventsAndUsage():void{$db=Mockery::mock(Db::class);$sql=[];$db->shouldReceive('statement')->times(3)->withArgs(function(string$s)use(&$sql){$sql[]=$s;return true;})->andReturnTrue();(new MeteringSchemaService($db))->ensureSchema();$all=implode("\n",$sql);self::assertStringContainsString('gateway_routes',$all);self::assertStringContainsString('gateway_call_events',$all);self::assertStringContainsString('usage_aggregates',$all);self::assertStringContainsString('UNIQUE KEY `uniq_event_id`',$all);}public function testEventIsStreamedAndPersistedIdempotently():void{$db=Mockery::mock(Db::class);$redis=Mockery::mock(Redis::class);$ids=Mockery::mock(IdGeneratorInterface::class);$redis->shouldReceive('xAdd')->once()->andReturn('1-0');$ids->shouldReceive('generate')->once()->andReturn(88);$db->shouldReceive('insert')->once()->withArgs(fn(string$sql)=>str_contains($sql,'ON DUPLICATE KEY UPDATE `event_id`=`event_id`'))->andReturnTrue();$s=new MeteringService($db,$redis,$ids);$s->emit(['event_id'=>'evt-1','subscription_id'=>9,'status_code'=>200,'duration_ms'=>12]);$s->persist(['event_id'=>'evt-1','subscription_id'=>9,'status_code'=>200,'duration_ms'=>12]);self::addToAssertionCount(1);}}
